// Freebuff Android — protocol reference validator (dependency-free)
// Mirrors upstream host-contract semantics captured at commit
// 25f1d61530c6d58db394b59db12e97c113e9322d so the Android host can bind to a
// contract with executable evidence. Source of truth stays upstream; this file
// MUST be regenerated by scripts/sync-upstream-contracts.sh when upstream drifts.

// --- FileChangeSchema (common/src/actions.ts) ---
const FILE_CHANGE_TYPES = ['patch', 'file'];
export function validateFileChange(obj) {
  const errs = [];
  if (typeof obj !== 'object' || obj === null) return ['file change must be an object'];
  if (!FILE_CHANGE_TYPES.includes(obj.type))
    errs.push(`type must be one of ${JSON.stringify(FILE_CHANGE_TYPES)}`);
  if (typeof obj.path !== 'string' || obj.path.length === 0)
    errs.push('path must be a non-empty string');
  if (typeof obj.content !== 'string') errs.push('content must be a string');
  return errs;
}

// --- run_terminal_command timeout clamp (params/tool/run-terminal-command.ts) ---
export const MAX_TERMINAL_TIMEOUT_SECONDS = 600;
export function clampTerminalTimeoutSeconds(seconds) {
  if (seconds === undefined) return undefined; // leave to schema default (30)
  if (seconds === -1) return -1;               // explicit indefinite sentinel
  if (!Number.isFinite(seconds)) return MAX_TERMINAL_TIMEOUT_SECONDS;
  if (seconds <= 0) return 30;                 // nonsense -> default, not instant-fail
  return Math.min(seconds, MAX_TERMINAL_TIMEOUT_SECONDS);
}

// --- clientToolCallSchema (common/src/tools/list.ts) : the 16 host tools ---
export const CLIENT_TOOL_NAMES = [
  'apply_patch', 'ask_user', 'browser_logs', 'code_search', 'create_plan',
  'glob', 'list_directory', 'run_file_change_hooks', 'read_url',
  'run_terminal_command', 'str_replace', 'write_file',
  'composio_manage_connections', 'composio_multi_execute_tool',
  'composio_search_tools', 'composio_get_tool_schemas',
];

// Tools whose input is a FileChangeSchema per upstream clientToolCallSchema.
const FILE_CHANGE_TOOLS = ['create_plan', 'str_replace', 'write_file'];

function validateRunTerminalInput(input) {
  const errs = [];
  if (typeof input.command !== 'string' || input.command.length < 1)
    errs.push('command cannot be empty');
  if (input.process_type !== undefined && !['SYNC', 'BACKGROUND'].includes(input.process_type))
    errs.push('process_type must be SYNC or BACKGROUND');
  if (input.cwd !== undefined && typeof input.cwd !== 'string')
    errs.push('cwd must be a string');
  // mode: {assistant|user} is appended by clientToolCallSchema for client dispatch.
  if (!['assistant', 'user'].includes(input.mode))
    errs.push("client dispatch requires mode: 'assistant' | 'user'");
  return errs;
}

// Discriminated union validator: returns {ok, errors}
export function validateClientToolCall(action) {
  const errors = [];
  if (typeof action !== 'object' || action === null)
    return { ok: false, errors: ['action must be an object'] };
  const { toolName, input } = action;
  if (!CLIENT_TOOL_NAMES.includes(toolName)) {
    // §26: fail loudly on unknown/newly-introduced tools, never silently ignore.
    return { ok: false, errors: [`unsupported upstream tool: ${String(toolName)}`] };
  }
  if (typeof input !== 'object' || input === null) {
    return { ok: false, errors: [`${toolName}: input must be an object`] };
  }
  if (FILE_CHANGE_TOOLS.includes(toolName)) {
    const fc = validateFileChange(input);
    if (fc.length) errors.push(`${toolName}: FileChangeSchema -> ${fc.join('; ')}`);
  } else if (toolName === 'run_terminal_command') {
    errors.push(...validateRunTerminalInput(input));
  }
  // apply_patch / code_search / glob / list_directory / read_url / ask_user /
  // browser_logs / run_file_change_hooks / composio_* : presence-checked only in
  // this reference; full per-field schemas are generated from upstream params.
  return { ok: errors.length === 0, errors };
}
